      calls.push("value.valueOf");
      return 1;
    }
  };

  var ta = new TA(makeCtorArg(8));
  assert.throws(TypeError, function() {
    Atomics.add(ta, index, value);
  });
  assert.compareArray(calls, []);
}, null, ["immutable"]);
}
