};

const toPrimitive = {
  [Symbol.toPrimitive]() {
    return true;
  }
};

let outcomes = [];
let lifespan = 1000;
let start = $262.agent.monotonicNow();

(function wait() {
  let elapsed = $262.agent.monotonicNow() - start;

  if (elapsed > lifespan) {
    $DONE('Test timed out');
    return;
  }

  if (outcomes.length) {
